ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	AZsign:
	{
	    WebHook: 
	    {
	        Atributos: payload.Envelope.Body.WebHook.@,
	        Cuenta: payload.Envelope.Body.WebHook.Cuenta.@,
	        Ambito:
	        {
	            Atributos: payload.Envelope.Body.WebHook.Ambito.@,
	            Aplicacion: payload.Envelope.Body.WebHook.Ambito.Aplicacion.@
	        },
	        Evento: payload.Envelope.Body.WebHook.Evento.@,
	        AcuerdoInfo: 
	        {
	            Atributos: payload.Envelope.Body.WebHook.AcuerdoInfo.@,
	            Estado: payload.Envelope.Body.WebHook.AcuerdoInfo.Estado.@,
	            Cuenta: payload.Envelope.Body.WebHook.AcuerdoInfo.Cuenta.@,
	            GrupoRegistro: payload.Envelope.Body.WebHook.AcuerdoInfo.GrupoRegistro.@,
	            Origen: payload.Envelope.Body.WebHook.AcuerdoInfo.Origen.@,
	            GruposPartcipantes:  payload.Envelope.Body.WebHook.AcuerdoInfo.GruposPartcipantes pluck ($.Participante.@),
	            Mensaje: payload.Envelope.Body.WebHook.AcuerdoInfo.Mensaje,
	            Observacionnes: payload.Envelope.Body.WebHook.AcuerdoInfo.Observacionnes,
	            Documentos: 
	            {
                    Atributos: payload.Envelope.Body.WebHook.AcuerdoInfo.Documentos pluck ($.@),
                    Documento: payload.Envelope.Body.WebHook.AcuerdoInfo.Documentos pluck ($)
                },
               	Copias: payload.Envelope.Body.WebHook.AcuerdoInfo.Copias
	        }
	    } 
	}
}

%dw 2.0
output application/json
var estado = payload.AZsign.WebHook.AcuerdoInfo.Estado.Nombre
---
{
	EstadoTramite: if(estado == "Finalizado") "Aprobado"
		else if(estado == "Abortado") "Cancelado"
		else estado,
	FechaActualizacionTramite: payload.AZsign.WebHook.Evento.FechaHora
}
